#include <algorithm>
#include <fstream>
#include <string>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    string s; if (!(in >> s)) return;
    int n=int(s.size()); vector<int> balance(n+1,0), before(n+1), suffix(n+1);
    for (int i=0;i<n;++i) balance[i+1]=balance[i]+(s[i]=='('?1:-1);
    before[0]=0;
    for (int i=1;i<=n;++i) before[i]=min(before[i-1],balance[i]);
    suffix[n]=balance[n];
    for (int i=n-1;i>=0;--i) suffix[i]=min(balance[i],suffix[i+1]);
    int answer=0;
    for (int i=0;i<n;++i) {
        int change=s[i]=='('? -2:2;
        if (balance[n]+change==0 && before[i]>=0 && suffix[i+1]+change>=0) ++answer;
    }
    out << answer << '\n';
}
int main() { ifstream in("typo.in"); ofstream out("typo.out"); solve(in,out); return 0; }
