#include <algorithm>
#include <cstdint>
#include <fstream>
#include <string>
#include <vector>
using namespace std;
void search(int at, uint32_t used, int opens, int closes, const vector<string>& grid, int& best) {
    int n=int(grid.size());
    if (opens>n*n/2) return;
    if (closes==opens) { best=max(best,opens+closes); return; }
    int r=at/n, c=at%n;
    const int dr[]={-1,1,0,0}, dc[]={0,0,-1,1};
    for (int d=0;d<4;++d) {
        int rr=r+dr[d], cc=c+dc[d];
        if (rr<0 || rr>=n || cc<0 || cc>=n) continue;
        int next=rr*n+cc; uint32_t bit=uint32_t(1)<<next;
        if (used&bit) continue;
        if (grid[rr][cc]=='(') {
            if (closes==0) search(next,used|bit,opens+1,0,grid,best);
        } else if (closes<opens) search(next,used|bit,opens,closes+1,grid,best);
    }
}
void solve(istream& in, ostream& out) {
    int n; if (!(in >> n)) return;
    vector<string> grid(n); for (string& row:grid) in >> row;
    int best=0;
    if (grid[0][0]=='(') search(0,uint32_t(1),1,0,grid,best);
    out << best << '\n';
}
int main() { ifstream in("hshoe.in"); ofstream out("hshoe.out"); solve(in,out); return 0; }
